    /// <summary>
    /// The name the game would show. Falls back to the asset name, which is
    /// what a level added after this table was generated will land on.
    /// </summary>
    public static string Display(string? asset) =>
        asset is not null && Known.TryGetValue(asset, out var e) && e.Name.Length > 0
            ? e.Name
            : asset ?? "";

    /// <summary>The short code the game uses in ghost links, or "".</summary>
    public static string Code(string? asset) =>
        asset is not null && Known.TryGetValue(asset, out var e) ? e.Code : "";

    /// <summary>True when the game has a name of its own for this level.</summary>
    public static bool IsKnown(string? asset) =>
        asset is not null && Known.ContainsKey(asset);

    /// <summary>How many levels the table covers.</summary>
    public static int Count => Known.Count;
}
